const int MOD = 998244353;

template<ll mod> // template was not stolen from https://codeforces.com/profile/SharpEdged
struct modnum {
    static constexpr bool is_big_mod = mod > numeric_limits<int>::max();

    using S = conditional_t<is_big_mod, ll, int>;
    using L = conditional_t<is_big_mod, __int128, ll>;

    S x;

    modnum() : x(0) {}
    modnum(ll _x) {
        _x %= static_cast<ll>(mod);
        if (_x < 0) { _x += mod; }
        x = _x;
    }

    modnum pow(ll n) const {
        modnum res = 1;
        modnum cur = *this;
        while (n > 0) {
            if (n & 1) res *= cur;
            cur *= cur;
            n /= 2;
        }
        return res;
    }
    modnum inv() const { return (*this).pow(mod-2); }

    modnum& operator+=(const modnum& a){
        x += a.x;
        if (x >= mod) x -= mod;
        return *this;
    }
    modnum& operator-=(const modnum& a){
        if (x < a.x) x += mod;
        x -= a.x;
        return *this;
    }
    modnum& operator*=(const modnum& a){
        x = static_cast<L>(x) * a.x % mod;
        return *this;
    }
    modnum& operator/=(const modnum& a){ return *this *= a.inv(); }

    friend modnum operator+(const modnum& a, const modnum& b){ return modnum(a) += b; }
    friend modnum operator-(const modnum& a, const modnum& b){ return modnum(a) -= b; }
    friend modnum operator*(const modnum& a, const modnum& b){ return modnum(a) *= b; }
    friend modnum operator/(const modnum& a, const modnum& b){ return modnum(a) /= b; }

    friend bool operator==(const modnum& a, const modnum& b){ return a.x == b.x; }
    friend bool operator!=(const modnum& a, const modnum& b){ return a.x != b.x; }
    friend bool operator<(const modnum& a, const modnum& b){ return a.x < b.x; }

    friend ostream& operator<<(ostream& os, const modnum& a){ os << a.x; return os; }
    friend istream& operator>>(istream& is, modnum& a) { ll x; is >> x; a = modnum(x); return is; }
};

using mint = modnum<MOD>;

template <class T> struct SegTree{
    vector<T> seg;
    int n;
    const T ID = 0;

    T cmb(T a, T b){
        return max(a, b);
    }

    SegTree(int _n){
        n = 1;
        while (n < _n) n *= 2;
        seg.assign(2 * n + 1, ID);
    }

    void set(int pos, T val){
        seg[pos + n] = val;
    }

    void build(){
        for (int i = n - 1; i >= 1; i--) seg[i] = cmb(seg[2 * i], seg[2 * i + 1]);
    }

    void upd(int v, int tl, int tr, int pos, T val){
        if (tl == tr){
            seg[v] = val;
        } else {
            int tm = (tl + tr) / 2;
            if (pos <= tm) upd(2 * v, tl, tm, pos, val);
            else upd(2 * v + 1, tm + 1, tr, pos, val);
            seg[v] = cmb(seg[2 * v], seg[2 * v + 1]);
        }
    }

    void upd(int pos, T val){
        upd(1, 0, n - 1, pos, val);
    }

    T query(int v, int tl, int tr, int l, int r){
        if (l > r) return ID;
        if (l == tl && r == tr) return seg[v];
        int tm = (tl + tr) / 2;
        T res = query(2 * v, tl, tm, l, min(tm, r));
        res = cmb(res, query(2 * v + 1, tm + 1, tr, max(l, tm + 1), r));
        return res;
    }

    T query(int l, int r){
        return query(1, 0, n - 1, l, r);
    }
};

struct DSU{
    vector<int> p, sz, used, mn, mx;

    DSU(int n){
        p.assign(n, 0);
        sz.assign(n, 1);
        used.assign(n, 0);
        mx.assign(n, 0);
        mn.assign(n, 0);

        for (int i = 0; i < n; i++) p[i] = i;
    }

    int find(int u){
        if (p[u] == u) return u;
        p[u] = find(p[u]);
        return p[u];
    }

    void unite(int u, int v){
        u = find(u);
        v = find(v);
        if (u == v) return;

        if (sz[u] < sz[v]) swap(u, v);
        p[v] = u;
        sz[u] += sz[v];
        used[u] += used[v];
        mn[u] = min(mn[u], mn[v]);
        mx[u] = max(mx[u], mx[v]);
    }

    bool same(int u, int v){
        return find(u) == find(v);
    }

    int size(int u){
        u = find(u);
        return sz[u];
    }
};

void solve(){
    int n;
    cin >> n;

    vector<int> a(n), b(n);
    for (int &x : a) cin >> x;
    for (int &x : b) cin >> x;

    vector<vector<int>> col(n + 1);
    for (int i = 0; i < n; i++){
        col[b[i]].push_back(i);
    }

    vector<vector<int>> ord(n + 1);

    for (int i = 0; i <= n; i++){
        ord[i] = col[i];
        sort(ord[i].begin(), ord[i].end(), [&](int x, int y) -> bool{
            return a[x] < a[y];
        });
    }

    SegTree<int> seg(n);
    for (int i = 0; i < n; i++){
        seg.set(i, a[i]);
    } seg.build();

    mint ans = 1;
    DSU dsu(n);
    for (int i = 0; i <= n; i++){
        for (int j = 0; j < col[i].size(); j++){
            dsu.mn[col[i][j]] = j;
            dsu.mx[col[i][j]] = j;
        }
    }

    for (int i = 0; i <= n; i++){
        for (int x : ord[i]) seg.upd(x, 0);

        for (int x : ord[i]){
            int idx = lower_bound(col[i].begin(), col[i].end(), x) - col[i].begin();
            for (int j = idx + 1; j < col[i].size(); j++){
                if (seg.query(x, col[i][j]) >= a[x]) break;

                dsu.unite(x, col[i][j]);
                j = dsu.mx[dsu.find(x)];
            }

            for (int j = idx - 1; j >= 0; j--){
                if (seg.query(col[i][j], x) >= a[x]) break;

                dsu.unite(x, col[i][j]);
                j = dsu.mn[dsu.find(x)];
            }

            int u = dsu.find(x);
            ans *= dsu.size(u) - dsu.used[u];
            dsu.used[u]++;
        }

        for (int x : ord[i]) seg.upd(x, a[x]);
    }

    cout << ans << "\n";
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}

#include<bits/stdc++.h>
using namespace std;
typedef long long ll;
#define debug(x) cout << #x << " = " << x << "\n";
#define vdebug(a) cout << #a << " = "; for(auto x: a) cout << x << " "; cout << "\n";
